#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.UI;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad]public static class LobbyBrandApply {
static LobbyBrandApply(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("Temp/Mok-lobby-brand-request"))return;File.Delete("Temp/Mok-lobby-brand-request");try{Apply();File.WriteAllText("Temp/Mok-lobby-brand.txt","PASS: warm palette, pizza delivery symbol, Korean subtitle saved.");}catch(Exception e){File.WriteAllText("Temp/Mok-lobby-brand.txt",e.ToString());}}
static RectTransform Rect(Transform p,string name,float x0,float y0,float x1,float y1){var t=p.Find(name);var r=t?(RectTransform)t:new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(p,false);r.anchorMin=new Vector2(x0,y0);r.anchorMax=new Vector2(x1,y1);r.offsetMin=r.offsetMax=Vector2.zero;return r;}
static void Apply(){var scene=SceneManager.GetSceneByPath("Assets/Scenes/Lobby.unity");if(!scene.isLoaded)scene=EditorSceneManager.OpenScene("Assets/Scenes/Lobby.unity",OpenSceneMode.Additive);EditorSceneManager.SaveScene(scene,"Temp/Mok-lobby-before-brand.unity",true);var c=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<LobbyController>(true)).Single();Color orange=new Color32(192,99,48,255),brown=new Color32(94,60,43,255),cream=new Color32(255,239,213,255);
foreach(var b in new[]{c.startButton,c.settingsButton,c.quitButton,c.backButton,c.screenButton}){b.GetComponent<Image>().color=b==c.startButton||b==c.backButton?orange:brown;var colors=b.colors;colors.highlightedColor=new Color(1,.88f,.70f);colors.selectedColor=colors.highlightedColor;colors.pressedColor=new Color(.8f,.65f,.5f);b.colors=colors;foreach(var t in b.GetComponentsInChildren<Text>())t.color=cream;}
c.menu.transform.Find("Accent").GetComponent<Image>().color=orange;
foreach(var t in c.menu.GetComponentsInChildren<Text>())if(t.text=="DELIVERY"||t.text=="SERVICE"){t.color=cream;var r=t.rectTransform;r.anchorMin=new Vector2(.145f,r.anchorMin.y);r.anchorMax=new Vector2(.49f,r.anchorMax.y);}
var icon=Rect(c.menu.transform,"Delivery Symbol",.065f,.735f,.13f,.845f);var symbol=icon.GetComponent<DeliveryBrandSymbol>()??icon.gameObject.AddComponent<DeliveryBrandSymbol>();symbol.raycastTarget=false;
var sub=Rect(c.menu.transform,"Genre Subtitle",.07f,.59f,.44f,.64f);var label=sub.GetComponent<Text>()??sub.gameObject.AddComponent<Text>();label.font=AssetDatabase.LoadAssetAtPath<Font>("Assets/Fonts/BMJUA_ttf.ttf");label.text="피자 배달 경영 타이쿤";label.fontSize=25;label.color=cream;label.alignment=TextAnchor.MiddleLeft;label.raycastTarget=false;
var window=c.settingsPanel.transform.Find("Settings Window");window.GetComponent<Image>().color=new Color32(249,241,226,255);foreach(var t in window.GetComponentsInChildren<Text>(true))if(!t.GetComponentInParent<Button>())t.color=brown;
foreach(var s in new[]{c.bgm,c.sfx}){s.fillRect.GetComponent<Image>().color=orange;s.handleRect.GetComponent<Image>().color=brown;s.transform.Find("Track").GetComponent<Image>().color=new Color32(220,207,187,255);}
EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Capture(c);}
static void Capture(LobbyController c){var canvas=c.menu.GetComponentInParent<Canvas>();var cam=c.lobbyCamera;var rt=new RenderTexture(1600,900,24);var previous=RenderTexture.active;var mode=canvas.renderMode;var wc=canvas.worldCamera;var distance=canvas.planeDistance;try{canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=1;cam.targetTexture=rt;Canvas.ForceUpdateCanvases();cam.Render();RenderTexture.active=rt;var image=new Texture2D(1600,900,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1600,900),0,0);image.Apply();File.WriteAllBytes("Temp/Mok-lobby-brand.png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}finally{cam.targetTexture=null;canvas.renderMode=mode;canvas.worldCamera=wc;canvas.planeDistance=distance;RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
}
}
#endif
